let name=d=>lang==='zh-Hant'?d.zh:d.en;
const assetUrl=d=>`https://cdn.jsdelivr.net/npm/openmoji@15.1.0/color/svg/${d.code}.svg`;
function icon(k){const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',case:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12h18M10 12v3h4v-3"/>',book:'<path d="M12 6c-3-3-7-3-10-2v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-4-1-7 0-10 2v15"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',chart:'<path d="M3 3v18h18M7 16v-5M12 16V7M17 16V4"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z"/>',check:'<path d="m5 12 4 4L20 5"/>',edit:'<path d="m14 4 6 6M3 21l5-1L21 7l-5-5L3 15v6Z"/>',devices:'<rect x="2" y="3" width="15" height="12" rx="2"/><rect x="16" y="9" width="6" height="12" rx="1"/><path d="M5 20h8M9 15v5"/>'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.grid}</svg>`}
function brand(){return `<span class="brand"><svg viewBox="0 0 28 28" aria-hidden="true"><path d="M18.8284 6.52789L10.7874 22.3344C10.4708 22.9565 9.84135 23.3143 9.18884 23.3133C8.5363 23.3143 7.90679 22.9565 7.59028 22.3344L0.303865 8.01144C0.123791 7.65747 0.0723965 7.27171 0.132331 6.90766C0.230545 6.01094 0.989343 5.31326 1.91084 5.31326H11.237C11.9815 5.31326 12.6199 5.76871 12.8894 6.41661L13.2697 7.16426L11.2606 11.1101L10.135 8.89753H4.77106L9.18879 17.5815L14.8571 6.4393C15.2086 5.74839 15.9181 5.31326 16.6933 5.31326H20.6196C20.2672 5.32684 19.9357 5.42725 19.6251 5.6145C19.3269 5.79427 19.0688 6.08473 18.8509 6.48589Z" fill="#ff1b1f"/><path d="M21.8492 5.31326C21.4967 5.32684 21.1652 5.42725 20.8546 5.6145C20.5564 5.79427 20.2983 6.08473 20.0804 6.48589L18.8524 8.89755H22.9864L18.5689 17.5809L16.5019 13.5179L14.4888 17.4557L16.9724 22.3377C17.2845 22.9494 17.9004 23.3045 18.5651 23.3133C19.2404 23.3029 19.8541 22.948 20.1655 22.3377L27.4558 8.00733C27.6014 7.72111 27.6626 7.41412 27.6487 7.10242C27.6487 6.1143 26.8477 5.31326 25.8597 5.31326Z" fill="#ff1b1f"/></svg>WPS Office<small>Templates</small></span>`}
function art(d,pg=1){if(d.type==='assets')return `<div class="assetcover"><img src="${assetUrl(d)}" alt="${esc(name(d))}" loading="lazy" onerror="this.style.display='none';this.parentNode.innerHTML='<span>OpenMoji · ${d.code}</span>'"></div>`;
let c=d.color;let inner='';const lines=(n,x0,y0,w,step=9)=>Array.from({length:n},(_,i)=>`<rect x="${x0}" y="${y0+i*step}" width="${i%3===2?w*.7:w}" height="2" fill="#cdd3da"/>`).join('');
if(['sheet','invoice','timeline'].includes(d.look)){inner=`<rect width="420" height="280" fill="${d.look==='invoice'?'#eaf1f4':'#eef4f0'}"/><rect x="30" y="22" width="360" height="238" rx="2" fill="white"/><text x="49" y="51" font-size="16" font-weight="700" fill="${c}">${esc(d.label)}</text><text x="49" y="67" font-size="6" fill="#8a9693">PLANNING WORKSHEET · 2026 / ${pg.toString().padStart(2,'0')}</text><rect x="49" y="84" width="322" height="20" fill="${c}"/><text x="58" y="97" fill="white" font-size="7">${d.look==='invoice'?'DESCRIPTION':'CATEGORY'}</text><text x="260" y="97" fill="white" font-size="7">PLAN</text><text x="325" y="97" fill="white" font-size="7">ACTUAL</text>${Array.from({length:8},(_,i)=>`<rect x="49" y="${105+i*15}" width="322" height="15" fill="${i%2?'white':'#f2f6f5'}"/><path d="M49 ${120+i*15}H371M246 ${105+i*15}v15M308 ${105+i*15}v15" stroke="#dce5e1" stroke-width=".6"/><text x="58" y="${115+i*15}" font-size="6.5" fill="#667b75">${['Operations','Marketing','Travel','Supplies','Software','Team','Other','Total'][i]}</text>${d.look==='timeline'?`<rect x="${250+i%3*20}" y="${109+i*15}" width="${35+i%2*20}" height="7" rx="2" fill="${c}" opacity=".6"/>`:`<text x="260" y="${115+i*15}" font-size="6.5" fill="#68716c">${(i+1)*150}.00</text><text x="325" y="${115+i*15}" font-size="6.5" fill="#68716c">${(i+1)*125}.00</text>`}`).join('')}<rect x="49" y="234" width="322" height="3" fill="${c}"/>`}
else if(['resume','letter'].includes(d.look)){inner=`<rect width="420" height="280" fill="#edf0f5"/><rect x="110" y="15" width="200" height="260" fill="white"/><rect x="110" y="15" width="${d.look==='resume'?58:6}" height="260" fill="${c}"/><text x="${d.look==='resume'?180:137}" y="48" font-size="13" font-weight="700" fill="${c}">${esc(d.label)}</text><text x="180" y="63" font-size="5" fill="#7a858f">DESIGN / EXPERIENCE / IDEAS</text>${lines(3,180,80,110,7)}<text x="180" y="118" font-size="6" fill="${c}">EXPERIENCE</text>${lines(6,180,131,105,7)}<text x="180" y="191" font-size="6" fill="${c}">EDUCATION & SKILLS</text>${lines(6,180,202,105,7)}${d.look==='resume'?`<circle cx="139" cy="48" r="15" fill="#ffffff45"/>${lines(10,119,84,38,12)}`:''}`}
else if(d.look==='lesson'){inner=`<rect width="420" height="280" fill="#f1f1df"/><circle cx="388" cy="7" r="110" fill="#e1e7be"/><path d="M0 230Q130 175 240 280H0Z" fill="#d9e2ca"/><text x="35" y="43" font-size="7" letter-spacing="2" fill="${c}">LEARN SOMETHING NEW / ${pg}</text><text x="34" y="99" font-size="34" font-family="Georgia" fill="#29473e">A world of</text><text x="34" y="140" font-size="37" font-family="Georgia" fill="#29473e">discovery.</text><path d="M300 217V125M300 170q-55-4-49-46 51 0 49 46M300 145q45-5 41-42-43 0-41 42" fill="#609b7d" stroke="#3d705b" stroke-width="3"/><path d="M267 218h68l-10 33h-48Z" fill="#c6a478"/><text x="36" y="204" font-size="8" fill="#738270">IDEAS THAT GROW WITH YOU</text>`}
else if(d.look==='portfolio'){inner=`<rect width="420" height="280" fill="#f4dfca"/><path d="M255 0h165v280H255Z" fill="${c}"/><circle cx="332" cy="123" r="62" fill="#f1c881"/><rect x="278" y="105" width="108" height="150" rx="50" fill="#d4e6de"/><circle cx="334" cy="148" r="31" fill="#244d5b"/><text x="28" y="45" font-size="7" letter-spacing="2" fill="${c}">A COLLECTION OF IDEAS / ${pg}</text><text x="28" y="111" font-size="31" font-family="Georgia" fill="#34312e">${d.label.split(' ').slice(0,2).join(' ')}</text><text x="28" y="150" font-size="29" font-family="Georgia" fill="#34312e">${d.label.split(' ').slice(2).join(' ')}</text><path d="M30 190h100" stroke="#6c6258"/><text x="30" y="214" font-size="8" fill="#8d786a">CREATE / EXPLORE / GROW</text>`}
else{inner=`<rect width="420" height="280" fill="${c}"/><circle cx="385" cy="215" r="139" fill="#ffffff08"/><circle cx="355" cy="210" r="90" fill="none" stroke="#ffffff35" stroke-width="1"/><path d="m263 269 82-130 87 130" fill="#ffffff10"/><text x="32" y="42" fill="#ffffff90" font-size="7" letter-spacing="2">STRATEGY / OUTLOOK / ${pg}</text><text x="32" y="117" font-size="33" font-family="Georgia" fill="white">${esc(d.label.split(' ').slice(0,2).join(' '))}</text><text x="32" y="159" font-size="33" font-family="Georgia" fill="white">${esc(d.label.split(' ').slice(2).join(' '))}</text><path d="M33 208h64" stroke="#a4c6df" stroke-width="2"/><text x="33" y="235" fill="#ffffff85" font-size="7">A CLEARER WAY FORWARD</text>`}
return `<svg viewBox="0 0 420 280" role="img" aria-label="${esc(name(d))}">${inner}</svg>`}
function head(){document.documentElement.lang=lang;document.title=`WPS ${t(0)} — ${t(6)}`;$('header').innerHTML=`<button onclick="go('home')" aria-label="WPS Templates Home">${brand()}</button><div class="globalnav"><a href="${locales.find(l=>l[0]===lang)[2]}" target="_blank" rel="noopener">${x('products')}⌄</a><a href="https://www.wps.com/tools/" target="_blank" rel="noopener">${x('tools')}⌄</a><a href="https://www.wps.com/pricing/" target="_blank" rel="noopener">${x('pricing')}</a><a href="https://www.wps.com/academy/" target="_blank" rel="noopener">${x('resources')}⌄</a><a href="https://help.wps.com/" target="_blank" rel="noopener">${x('support')}</a></div><div class="tools"><button class="globe" onclick="languages()" aria-label="${t(31)}">${icon('globe')}</button><button class="primary" onclick="handoff()">${t(4)}</button><button class="signin" onclick="notify(x('signin'))">${t(5)}</button></div>`;
$('subnav').innerHTML=`<strong>${t(0)}</strong><div class="subitems">${[['templates',0],['assets',1]].map(([k,i])=>`<div class="navdrop"><button class="navitem ${kind===k&&view==='browse'?'active':''}" onclick="browse('${k}')">${t(i)}⌄</button><div class="mega">${(k==='templates'?['DOCX','XLSX','PPTX','all']:['SVG','all']).map(f=>`<button onclick="fmt='${f}';browse('${k}')">${f==='all'?t(11):f} →</button>`).join('')}</div></div>`).join('')}<button class="navitem ${view==='scene'?'active':''}" onclick="go('scene')">${t(2)}</button><button class="navitem" onclick="go('home');document.getElementById('collections').scrollIntoView({behavior:'smooth'})">${t(3)}</button></div><button class="textlink" onclick="go('saved')">♡ ${t(20)}${saveSet.size?' ('+saveSet.size+')':''}</button>`;
footer()}
function footer(){$('footer').innerHTML=`<section class="cta"><h2>${t(29)}</h2><p>${t(30)}</p><button class="primary" onclick="handoff()">${t(4)} →</button></section><footer class="footer"><div class="wrap"><div class="footgrid"><div>${brand()}<p>WPS SOFTWARE PTE. LTD.<br>6 RAFFLES QUAY #14-06.<br>SINGAPORE (048580)</p></div><div><strong>${x('products')}</strong>${['Windows','Mac','Android','iOS'].map(os=>`<a href="https://www.wps.com/office/${os.toLowerCase()}/" target="_blank" rel="noopener">WPS Office · ${os}</a>`).join('')}</div><div><strong>${x('resources')}</strong><a href="#" onclick="event.preventDefault();browse('templates')">${t(0)}</a><a href="#" onclick="event.preventDefault();browse('assets')">${t(1)}</a><a href="#" onclick="event.preventDefault();go('scene')">${t(2)}</a><a href="https://www.wps.com/academy/" target="_blank" rel="noopener">WPS Academy</a></div><div><strong>${x('company')}</strong><a href="https://www.wps.com/about-us/" target="_blank" rel="noopener">${x('about')}</a><a href="https://help.wps.com/" target="_blank" rel="noopener">${x('support')}</a><a href="https://www.wps.com/privacy-policy/" target="_blank" rel="noopener">${x('legal')}</a><a href="#" onclick="event.preventDefault();credits()">${x('sourcelink')}</a></div></div><div class="footbottom"><span>${x('credit')}<br>© WPS brand belongs to Kingsoft. Concept demo / 2026.</span><button onclick="languages()">${icon('globe')} ${locales.find(l=>l[0]===lang)[1]} ⌄</button></div></div></footer>`}
function searchbox(){return `<form class="searchbox" onsubmit="event.preventDefault();q=this.querySelector('input').value;go('browse')">${icon('search')}<input aria-label="${t(9)}" placeholder="${t(9)}" value="${esc(q)}"><button class="primary">${t(10)}</button></form>`}
function card(d){return `<article class="card"><button class="heart ${saveSet.has(d.id)?'on':''}" aria-label="${saveSet.has(d.id)?t(20):t(19)}: ${esc(name(d))}" onclick="toggleSave(${d.id},this)">${saveSet.has(d.id)?'♥':'♡'}</button><button class="cover" onclick="selected=${d.id};page=1;go('detail')">${art(d)}</button><h3><button onclick="selected=${d.id};page=1;go('detail')">${esc(name(d))}</button></h3><div class="cardmeta"><span class="dot"></span>${d.format}<span>·</span>${d.filelang}<span style="margin-left:auto">${t(18)}</span></div></article>`}
function section(title,subtitle,items,action="browse('templates')"){return `<section class="section"><div class="sectionhead"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="textlink" onclick="${action}">${t(13)} →</button></div><div class="grid">${items.map(card).join('')}</div></section>`}
function home(){return `<section class="hero"><div class="eyebrow">WPS TEMPLATE LIBRARY</div><h1>${t(6)}<br><span>${t(7)}</span></h1><p>${t(8)}</p>${searchbox()}<div class="popular">${['Budget','Resume','Invoice','Teaching','Timeline'].map((s,i)=>`<button onclick="q='${s}';kind='all';go('browse')">${lang==='zh-Hant'?['預算','履歷','發票','教學','時間軸'][i]:s}</button>`).join('')}</div><div class="showcase" aria-hidden="true">${[0,1,2,3,4].map(i=>`<div class="mini">${art(records[i])}</div>`).join('')}</div></section><div class="wrap"><div class="formats">${[['W','', 'Word','DOCX'],['S','green','Excel','XLSX'],['P','orange','PowerPoint','PPTX'],['P','red','PDF','PDF']].map(([a,c,l,f])=>`<button onclick="fmt='${f}';browse('templates')"><span class="appicon ${c}">${a}</span>${l}</button>`).join('')}<button onclick="browse('assets')"><span class="appicon purple">✧</span>${t(1)}</button></div><section class="section"><div class="sectionhead"><div><h2>${x('task')}</h2><p>${x('taskdesc')}</p></div></div><div class="taskgrid">${[14,15,16,17].map((i,j)=>`<button class="task" onclick="taskBrowse(${i})"><span class="symbol">${icon(['case','person','book','chart'][j])}</span><strong>${t(i)}</strong><span class="arrow">↗</span></button>`).join('')}</div></section><section class="section"><div class="sectionhead"><div><h2>${t(12)}</h2><p>${x('popular')}</p></div><button class="textlink" onclick="browse('templates')">${t(13)} →</button></div><div class="tabs">${['all','XLSX','DOCX','PPTX'].map((f,i)=>`<button class="pill ${i===0?'active':''}" onclick="homeTab('${f}',this)">${i===0?t(11):f}</button>`).join('')}</div><div class="grid" id="homegrid">${records.slice(0,8).map(card).join('')}</div></section><section class="section" id="collections"><div class="sectionhead"><div><h2>${x('collection')}</h2><p>${x('collectiondesc')}</p></div></div><div class="collections">${[['teach','educaption',2,16],['plan','procaption',3,17],['career','careercaption',1,15]].map(([title,caption,id,task])=>`<button class="collection" onclick="sceneTask=${task};go('scene')"><strong>${x(title)}</strong><small>${x(caption)}</small><span>${t(13)} →</span><div class="art">${art(records[id])}</div></button>`).join('')}</div></section>${section(x('assets'),x('assetsdesc'),records.slice(16,20),"browse('assets')")}<section class="feature"><div class="featuretext"><div class="eyebrow">WPS OFFICE</div><h2>${x('feature')}</h2><p>${x('featuredesc')}</p><a class="primary" href="${locales.find(l=>l[0]===lang)[2]}" target="_blank" rel="noopener">${x('featurecta')} ↗</a></div><img src="https://global-static.wpscdn.com/cms/official-website/v2/_nuxt/allinone_img_slides.BNaETSwm.png" alt="WPS Slides" loading="lazy" onerror="this.style.display='none'"></section><section class="benefits">${x('benefits').map((s,i)=>`<div>${icon(['edit','check','devices'][i])}<strong>${s}</strong><p>${x('benefitdesc')[i]}</p></div>`).join('')}</section><section class="faq"><h2>${x('faqt')}</h2>${x('faq').map((f,i)=>`<details><summary>${f}</summary><p>${x('answers')[i]}</p></details>`).join('')}</section></div>`}
function browse(k){kind=k;go('browse')}
function homeTab(f,b){document.querySelectorAll('.tabs .pill').forEach(el=>el.classList.remove('active'));b.classList.add('active');$('homegrid').innerHTML=records.filter(d=>d.type==='templates'&&(f==='all'||d.format===f)).slice(0,8).map(card).join('')}
let taskFilter=null,sceneTask=16;
function taskBrowse(i){taskFilter=i;q='';fmt='all';kind='templates';go('browse')}
function filtered(){let list=records.filter(d=>(kind==='all'||d.type===kind)&&(fmt==='all'||d.format===fmt)&&(filelang==='all'||d.filelang===filelang)&&(!taskFilter||(d.scenarios||[d.task]).includes(taskFilter)));if(q.trim()){let key=q.trim().toLowerCase();const aliases={'預算':'budget','履歷':'resume','發票':'invoice','教學':'lesson','時間軸':'timeline','课件':'lesson','预算':'budget','简历':'resume','素材':'openmoji','book':'book','書本':'book'};key=aliases[key]||key;list=list.filter(d=>`${d.en} ${d.zh} ${d.tags||''} ${d.assetGroup||''} ${d.format} ${d.filelang} ${translations.en[d.task]} ${t(d.task)} ${d.type==='assets'?'openmoji':''}`.toLowerCase().includes(key))}if(sort==='name')list.sort((a,b)=>name(a).localeCompare(name(b),lang));if(sort==='newest')list.reverse();return list}
function listing(saved=false){let list=saved?records.filter(d=>saveSet.has(d.id)):filtered();return `<div class="wrap pagepad"><div class="bread"><button onclick="go('home')">WPS Templates</button> / ${saved?t(20):kind==='assets'?t(1):t(0)}</div><div class="browsehead"><div class="eyebrow">${saved?'YOUR LIBRARY':'EXPLORE THE LIBRARY'}</div><h1>${saved?x('saved'):taskFilter?t(taskFilter):kind==='assets'?t(1):t(0)}</h1>${saved?'':searchbox()}</div>${saved?'':`<div class="tabs">${[['all',11],['templates',0],['assets',1]].map(([k,i])=>`<button class="pill ${kind===k?'active':''}" onclick="kind='${k}';render()">${t(i)}</button>`).join('')}</div><div class="filterbar"><div><select aria-label="${t(24)}" onchange="fmt=this.value;render()">${['all','XLSX','DOCX','PPTX','SVG','PDF'].map(f=>`<option value="${f}" ${fmt===f?'selected':''}>${f==='all'?t(24):f}</option>`).join('')}</select><select aria-label="${t(23)}" onchange="filelang=this.value;render()">${['all','English','Thai','Indonesian','Japanese','—'].map(f=>`<option value="${f}" ${filelang===f?'selected':''}>${f==='all'?x('allLanguages'):f}</option>`).join('')}</select><button class="textlink" onclick="fmt='all';filelang='all';taskFilter=null;q='';render()">${t(25)}</button></div><select aria-label="Sort" onchange="sort=this.value;render()">${[['recommended',x('recommended')],['newest',x('newest')],['name',x('name')]].map(([k,v])=>`<option value="${k}" ${sort===k?'selected':''}>${v}</option>`).join('')}</select></div>`}<p class="resultcount">${list.length} ${x('count')}${q?' · '+esc(q):''}</p><div class="grid">${list.length?list.map(card).join(''):`<div class="empty"><h2>${t(26)}</h2><p>${saved?x('emptySaved'):t(27)}</p><button class="primary" onclick="fmt='all';filelang='all';taskFilter=null;q='';browse('all')">${t(13)}</button></div>`}</div></div>`}
function detail(){let d=records.find(d=>d.id===selected);let related=records.filter(a=>a.id!==d.id&&a.task===d.task);return `<div class="wrap"><div class="bread"><button onclick="go('browse')">${t(28)}</button> / ${d.format} / ${esc(name(d))}</div><div class="detailgrid"><div><div class="detailpreview">${art(d,page)}</div>${d.type==='templates'?`<div class="previewcontrols"><button onclick="page=Math.max(1,page-1);render()" aria-label="Previous page">←</button><span>${page} / 3</span><button onclick="page=Math.min(3,page+1);render()" aria-label="Next page">→</button></div>`:''}<p class="previewbadge">${d.type==='templates'?x('sample'):x('downloadNote')}</p></div><div class="detailinfo"><span class="label">${t(d.task)}</span><h1>${esc(name(d))}</h1><p>${d.type==='assets'?x('assetsdesc'):t(8)}</p><div class="facts"><div><small>${t(24)}</small>${d.format}</div><div><small>${t(23)}</small>${d.filelang}</div><div><small>${t(18)}</small>${d.type==='assets'?'CC BY-SA 4.0':'CC0 · '+x('sample')}</div><div><small>${d.type==='assets'?x('dimensions'):x('sample')}</small>${d.type==='assets'?'72 × 72 · vector':'3 concept pages'}</div></div><button class="primary" onclick="handoff(${d.id})">${t(21)} →</button><button class="outline" onclick="toggleSave(${d.id});render()">${saveSet.has(d.id)?'♥ '+t(20):'♡ '+t(19)}</button><p class="muted" style="font-size:12px">${x('languageNotice')}</p><div class="license">${x('license')}<br>${d.type==='assets'?`OpenMoji · CC BY-SA 4.0<br><a href="${assetUrl(d)}" target="_blank" rel="noopener">${x('viewAsset')} ↗</a>`:x('original')}</div></div></div><section class="scene-step"><h2>${x('how')}</h2><div class="flow">${x('steps').map((s,i)=>`<span>0${i+1} / ${s}</span>`).join('')}</div></section>${section(t(22),x('related'),related.slice(0,4),`taskBrowse(${d.task})`)}</div>`}
function scene(){let list=records.filter(d=>d.task===sceneTask);let cover=list.find(d=>d.type==='templates')||records[2];return `<div class="wrap"><div class="bread">WPS Templates / ${t(2)}</div><section class="scenehero"><div><div class="eyebrow">${t(2)}</div><h1>${t(sceneTask)}</h1><p>${x('taskdesc')}</p><button class="primary" onclick="taskBrowse(${sceneTask})">${t(13)} →</button></div>${art(cover)}</section><div class="tabs">${[14,15,16,17].map(i=>`<button class="pill ${i===sceneTask?'active':''}" onclick="sceneTask=${i};render()">${t(i)}</button>`).join('')}</div>${section('01 / '+t(0),x('collectiondesc'),list.filter(d=>d.type==='templates'),`taskBrowse(${sceneTask})`)}${list.some(d=>d.type==='assets')?section('02 / '+t(1),x('assetsdesc'),list.filter(d=>d.type==='assets'),"browse('assets')"):''}</div>`}
function go(v){view=v;render();window.scrollTo(0,0)}
function render(){head();$('main').innerHTML=view==='home'?home():view==='detail'?detail():view==='scene'?scene():listing(view==='saved');try{let url=new URL(location.href);url.searchParams.set('lang',lang);url.hash=view==='detail'?`resource-${selected}`:view;history.replaceState(null,'',url)}catch(e){}}
function toggleSave(id,b){saveSet.has(id)?saveSet.delete(id):saveSet.add(id);try{localStorage.setItem('wps-template-saved-v2',JSON.stringify([...saveSet]))}catch(e){}if(b){b.classList.toggle('on',saveSet.has(id));b.textContent=saveSet.has(id)?'♥':'♡';b.setAttribute('aria-label',(saveSet.has(id)?t(20):t(19))+': '+name(records.find(d=>d.id===id)))}notify(saveSet.has(id)?t(20):t(19));head()}
function notify(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,3500)}
function showModal(html){lastFocus=document.activeElement;$('modalbody').innerHTML=html;$('modal').setAttribute('aria-labelledby','modal-title');if(!$('modal').open)$('modal').showModal()}
function closeModal(){$('modal').close();lastFocus?.focus()}
function languages(){showModal(`<h2 class="dialogtitle" id="modal-title">${t(31)}</h2><p>${x('language')}</p><div class="languagegrid">${locales.map(([code,label])=>`<button lang="${code}" class="${code===lang?'active':''}" onclick="changeLanguage('${code}')">${label}${code===lang?' ✓':''}</button>`).join('')}</div>`)}
function changeLanguage(code){lang=code;closeModal();render()}
function handoff(id){let d=id?records.find(d=>d.id===id):null;showModal(`<div class="eyebrow">WPS OFFICE</div><h2 class="dialogtitle" id="modal-title">${d?esc(name(d)):t(29)}</h2><p>${x('choose')}</p><div class="tabs">${['Windows','macOS','Android','iOS'].map((os,i)=>`<button class="pill ${i===0?'active':''}" onclick="this.parentNode.querySelectorAll('button').forEach(b=>b.classList.remove('active'));this.classList.add('active')">${os}</button>`).join('')}</div><div class="flow"><span>01 / ${t(4)}</span><span>02 / ${x('install')}</span><span>03 / ${x('open')}</span></div><button class="primary" onclick="recovery(${id||0})">${t(4)}</button> <button class="textlink" onclick="recovery(${id||0})">${x('already')}</button><p class="stepnote">${x('mock')}</p>`)}
function recovery(id){showModal(`<h2 class="dialogtitle" id="modal-title">${x('ready')}</h2><p>${id?esc(name(records.find(d=>d.id===id))):t(30)}</p><div class="flow">${x('steps').map((s,i)=>`<span>0${i+1} / ${s}</span>`).join('')}</div><button class="primary" onclick="closeModal();notify(x('mock'))">${x('continue')}</button><p class="stepnote">${x('mock')}</p>`)}
function credits(){showModal(`<h2 class="dialogtitle" id="modal-title">${x('sourcelink')}</h2><p>WPS brand symbol & product artwork: <a href="https://www.wps.com/" target="_blank" rel="noopener">wps.com ↗</a>. WPS assets are not open source.</p><p>Illustrations by <a href="https://openmoji.org/" target="_blank" rel="noopener">OpenMoji</a> — HfG Schwäbisch Gmünd, Benedikt Groß, Daniel Utz, students and contributors. <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Unmodified SVG files served from OpenMoji 15.1.0.</p><p>Original template cover designs: CC0. Covers demonstrate visual direction; no editable Office files are included.</p><p>17-language core UI aligned to WPS language menu. Editorial copy currently localized in English and Traditional Chinese; other versions use English editorial fallback and require native review.</p>`)}
$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()});
const initial=location.hash.slice(1);if(initial.startsWith('resource-')){const id=Number(initial.slice(9));if(records.some(d=>d.id===id)){selected=id;view='detail'}}else if(['browse','scene','saved'].includes(initial))view=initial;

