const additions=[
['Payroll calculator','薪资计算表','sheet','XLSX','English',14,'PAYROLL CALCULATOR','payroll'],['Monthly income tracker','月度收支记录','sheet','XLSX','English',14,'INCOME & EXPENSES','income'],['Inventory control sheet','库存管理表','sheet','XLSX','English',14,'INVENTORY CONTROL','inventory'],['Employee shift schedule','员工排班表','timeline','XLSX','English',14,'SHIFT SCHEDULE','attendance'],['Purchase order','采购单','invoice','XLSX','English',14,'PURCHASE ORDER','invoice'],['Company profile','公司介绍','strategy','PPTX','English',14,'Our next chapter.','company'],['Employment certificate','工作经历证明','letter','DOCX','English',15,'CERTIFICATE OF EMPLOYMENT','cover'],['Authorization letter','授权信','letter','DOCX','English',15,'LETTER OF AUTHORIZATION','cover'],['Recommendation letter','推荐信','letter','DOCX','English',15,'A STRONG RECOMMENDATION','cover'],['Resignation letter','离职信','letter','DOCX','English',15,'RESIGNATION LETTER','cover'],['Graduate resume — minimal','毕业生简历 · 极简','resume','DOCX','English',15,'YOUR NEXT CHAPTER','resume'],['Work report','工作汇报','strategy','PPTX','English',14,'The work behind progress.','report'],['Student class report','学生课堂汇报','lesson','PPTX','English',16,'Learning together.','teaching'],['Project Gantt chart','项目甘特图','timeline','XLSX','English',17,'GANTT / PROJECT PLAN','project'],['Meeting agenda','会议议程','letter','DOCX','English',17,'MEETING AGENDA','project'],['Task tracker','任务追踪表','sheet','XLSX','English',17,'TEAM TASK TRACKER','project'],['ใบเสนอราคา — ธุรกิจ','泰语商务报价单','invoice','XLSX','Thai',14,'ใบเสนอราคา','invoice'],['ทะเบียนสินค้า','泰语库存管理','sheet','XLSX','Thai',14,'ทะเบียนสินค้า','inventory'],['รายรับรายจ่าย','泰语收支表','sheet','XLSX','Thai',14,'รายรับรายจ่าย','income'],['ตารางเวรพนักงาน','泰语员工排班','timeline','XLSX','Thai',14,'ตารางเวรพนักงาน','attendance'],['สรุปยอดขาย','泰语销售汇总','sheet','XLSX','Thai',14,'สรุปยอดขาย','report'],['Company profile Indonesia','印尼语公司介绍','strategy','PPTX','Indonesian',14,'Profil perusahaan','company'],['CV Indonesia','印尼语CV','resume','DOCX','Indonesian',15,'DAFTAR RIWAYAT HIDUP','resume'],['Surat lamaran kerja','印尼语求职信','letter','DOCX','Indonesian',15,'SURAT LAMARAN KERJA','cover'],['Materi pembelajaran','印尼语教学简报','lesson','PPTX','Indonesian',16,'Mari belajar bersama.','teaching'],['Personal budget','个人预算','sheet','XLSX','English',14,'PERSONAL BUDGET','budget'],['Business cash flow','企业现金流','sheet','XLSX','English',14,'CASH FLOW','income'],['Payslip','工资条','invoice','XLSX','English',14,'PAYSLIP','payroll'],['Sales summary','销售汇总','sheet','XLSX','English',14,'SALES SUMMARY','report'],['Simple quotation','简洁报价单','invoice','XLSX','English',14,'QUOTATION','invoice'],['Science lesson slides','科学教学课件','lesson','PPTX','English',16,'Explore. Ask. Discover.','teaching'],['Company letterhead','公司信笺','letter','DOCX','English',15,'YOUR COMPANY','cover']
];additions.forEach((r,i)=>records.push({id:100+i,en:r[0],zh:r[1],look:r[2],format:r[3],filelang:r[4],task:r[5],label:r[6],topic:r[7],scenarios:[r[5]],type:'templates',original:true,color:['#287a69','#315574','#906d57','#796d9a'][i%4]}));
function assetCategory(d){const s=d.sub;if(s==='arrow')return 'arrows';if(['math','geometric','currency'].includes(s))return s==='currency'?'finance':'charts';if(['book-paper','science','writing'].includes(s))return 'education';if(['office','computer','phone','mail','lock','tool'].includes(s))return 'office';if(s==='money')return 'finance';if(d.group==='animals-nature'||s==='sky-weather')return 'nature';if(d.group==='travel-places')return 'travel';return 'activities'}
CONFIG.openmoji.forEach((d,i)=>{const g=assetCategory(d);const scenarios=g==='education'?[16]:g==='office'?[14,17]:g==='finance'?[14]:g==='arrows'||g==='charts'?[17,14,16]:g==='nature'?[16]:g==='travel'?[16,14]:[16,14];records.push({id:1000+i,en:d.name,zh:d.name,code:d.code,look:'asset',format:'SVG',filelang:'—',task:scenarios[0],scenarios,type:'assets',assetGroup:g,tags:d.tags,author:d.author,topic:g,color:'#4967be'})});
const groups={office:['Office & technology','办公科技'],finance:['Finance & business','财务经营'],education:['Learning & science','教育科学'],arrows:['Arrows & flow','箭头流程'],charts:['Charts & geometry','图表几何'],nature:['Nature & classroom','自然科普'],travel:['Maps & transport','地图交通'],activities:['Activities & creativity','活动创意']};
function assetGroupName(g){return groups[g]?.[cn()?1:0]||g}
function eligible(d){return d.type==='assets'||profiles[market].languages.includes(d.filelang)}
function recommendationScore(d){if(!eligible(d))return -Infinity;let p=profiles[market];if(d.type==='templates')return (p.weights[d.topic]||2)*10+(d.filelang===p.languages[0]?8:0)+({XLSX:3,DOCX:2,PPTX:1}[d.format]||0);return (p.asset[d.assetGroup]||2)*10}
function rankResources(list,{cap=Infinity,limit=Infinity}={}){let pool=list.filter(eligible).slice().sort((a,b)=>recommendationScore(b)-recommendationScore(a)||a.id-b.id);let counts={},out=[];for(const d of pool){let k=d.type==='assets'?d.assetGroup:d.topic;if((counts[k]||0)>=cap)continue;counts[k]=(counts[k]||0)+1;out.push(d);if(out.length>=limit)break}return out}
function getHomeRecommendations(f='all',task='all'){return rankResources(records.filter(d=>d.type==='templates'&&(f==='all'||d.format===f)&&(task==='all'||d.scenarios.includes(Number(task)))),{cap:2,limit:12})}
const v2Head=head;head=function(){v2Head();$('subnav').insertAdjacentHTML('beforeend',`<button class="region-button" onclick="regions()">${icon('globe')} ${esc(marketName(market))}⌄</button>`)};
const v2Render=render;render=function(){v2Render();try{const url=new URL(location.href);url.searchParams.set('market',market);history.replaceState(null,'',url)}catch(e){}};
const v2ChangeLanguage=changeLanguage;changeLanguage=function(code){if(!explicitMarket)market={en:'US',fil:'PH',th:'TH',ms:'MY',id:'ID',hi:'IN'}[code]||'GLOBAL';v2ChangeLanguage(code);browsePage=1};
function regions(){showModal(`<h2 class="dialogtitle" id="modal-title">${bi('Choose your region','选择推荐地区')}</h2><p>${bi('Region and interface language are independent. Recommendations follow local work and learning needs.','地区与界面语言独立选择，推荐随当地工作与学习需求调整。')}</p><div class="languagegrid">${Object.keys(marketNames).map(k=>`<button class="${market===k?'active':''}" onclick="setMarket('${k}')">${marketName(k)} ${market===k?'✓':''}</button>`).join('')}</div><button class="textlink" onclick="recommendationInfo()">${bi('How these selections are made','查看选品依据')} →</button>`)}
function setMarket(k){market=k;explicitMarket=true;browsePage=1;closeModal();render()}
function recommendationInfo(){let p=profiles[market];const lead=getHomeRecommendations().slice(0,6);showModal(`<h2 class="dialogtitle" id="modal-title">${bi('Selected for','地区选品依据 ·')} ${marketName(market)}</h2><p>${esc(p.stage)}</p><ul>${(cn()?p.zhwhy:p.why).map(s=>`<li style="margin:12px 0">${esc(s)}</li>`).join('')}</ul><p>${bi('Editorial priorities from the operating plan, not measured live popularity. Assets are a supply pilot. No click or installation rates are fabricated.','依据运营规划配置的优先选品，并非实时热度榜。素材属于供给试点，不虚构点击、下载与安装率。')}</p><div class="stepnote">${bi('Current leading topics','当前优先主题')}：${[...new Set(lead.map(d=>topicNames[d.topic]?.[cn()?1:0]))].join(' / ')}<br>${bi('Only available file languages are eligible. Diversification allows at most two templates per topic in the main recommendations.','只选取可用文件语言；主推荐中同一主题最多两张，避免同类内容挤占首屏。')}</div><p><a href="WPS模板站地区推荐与运营验收.md" target="_blank">${bi('Read recommendation specification','查看完整推荐规则与数据口径')} ↗</a></p>`)}
function chooseCatalog(k,f='all',task='all',g='all'){kind=k;fmt=f;taskFilter=task==='all'?null:Number(task);assetGroup=g;filelang='all';q='';browsePage=1;go('browse')}
function topicChip(topic){let first=rankResources(records.filter(d=>d.type==='templates'&&d.topic===topic),{limit:1})[0];return `<button onclick="q='${first?esc(first.en.split(' ')[0]):topic}';fmt='all';kind='templates';taskFilter=null;assetGroup='all';browsePage=1;go('browse')">${topicNames[topic]?.[cn()?1:0]||topic}</button>`}
function pickRow(title,items,action,subtitle=''){return `<section class="section dense-section"><div class="sectionhead"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="textlink" onclick="${action}">${t(13)} →</button></div><div class="grid">${items.map(card).join('')}</div></section>`}
function assetShelf(){return `<section class="section"><div class="sectionhead"><div><h2>${bi('A visual library for every task','用海量视觉素材补全每项任务')}</h2><p>${CONFIG.openmoji.length} ${bi('independent open-source assets · Color + outline · SVG','个独立开源素材 · 彩色与线稿 · SVG')}</p></div><button class="textlink" onclick="chooseCatalog('assets')">${t(13)} →</button></div><div class="asset-category-grid">${Object.keys(groups).sort((a,b)=>(profiles[market].asset[b]||0)-(profiles[market].asset[a]||0)).map(g=>{let arr=records.filter(d=>d.type==='assets'&&d.assetGroup===g);return `<button class="asset-category" onclick="chooseCatalog('assets','SVG','all','${g}')"><div class="asset-mosaic">${arr.slice(0,4).map(d=>art(d)).join('')}</div><strong>${assetGroupName(g)}</strong><span>${arr.length} SVG →</span></button>`}).join('')}</div></section>`}
home=function(){let p=profiles[market];let topics=Object.entries(p.weights).sort((a,b)=>b[1]-a[1]).slice(0,5).map(a=>a[0]);let rec=getHomeRecommendations(homeFormat,homeTask);let assets=rankResources(records.filter(d=>d.type==='assets'),{cap:3,limit:12});let templates=records.filter(d=>d.type==='templates');return `<section class="hero"><div class="eyebrow">WPS TEMPLATE & VISUAL LIBRARY</div><h1>${t(6)}<br><span>${t(7)}</span></h1><p>${t(8)}</p>${searchbox()}<div class="popular">${topics.map(topicChip).join('')}</div><div class="showcase" aria-hidden="true">${getHomeRecommendations().slice(0,5).map(d=>`<div class="mini">${art(d)}</div>`).join('')}</div></section><div class="wrap"><div class="catalog-bar"><div><b>${CONFIG.openmoji.length}</b><span>${bi('open-source visuals','独立开源素材')}</span></div><div><b>${templates.length}</b><span>${bi('template concept previews','模板概念预览')}</span></div><div><b>8</b><span>${bi('visual categories','素材主题分类')}</span></div><div><b>17</b><span>${bi('interface languages','界面语言')}</span></div><button class="region-button" onclick="regions()">${icon('globe')} ${marketName(market)}⌄</button></div><div class="formats">${[['W','','Word','DOCX'],['S','green','Excel','XLSX'],['P','orange','PowerPoint','PPTX']].map(([a,c,l,f])=>`<button onclick="chooseCatalog('templates','${f}')"><span class="appicon ${c}">${a}</span>${l}<small>${templates.filter(d=>d.format===f).length}</small></button>`).join('')}<button onclick="chooseCatalog('assets','SVG')"><span class="appicon purple">S</span>SVG<small>${CONFIG.openmoji.length}</small></button><button onclick="chooseCatalog('assets','SVG');assetStyle='black';render()">${bi('Outline icons','线稿图标')} →</button></div><section class="section"><div class="sectionhead"><div><h2>${x('task')}</h2><p>${x('taskdesc')}</p></div></div><div class="taskgrid">${[14,15,16,17].sort((a,b)=>Math.max(...templates.filter(d=>d.task===b).map(recommendationScore))-Math.max(...templates.filter(d=>d.task===a).map(recommendationScore))).map((i,j)=>`<button class="task" onclick="chooseCatalog('all','all','${i}')"><span class="symbol">${icon({14:'case',15:'person',16:'book',17:'chart'}[i])}</span><strong>${t(i)}</strong><span class="task-sub">${records.filter(d=>d.scenarios.includes(i)).length} ${x('count')}</span><span class="arrow">↗</span></button>`).join('')}</div></section><section class="section"><div class="sectionhead"><div><h2>${bi('Selected for','为你精选 ·')} ${marketName(market)}</h2><p>${bi('Office templates matched to regional work and learning needs.','按地区工作与学习需求精选办公模板。')}</p></div><button class="textlink" onclick="recommendationInfo()">${bi('Why these picks?','为什么推荐这些内容？')} ⓘ</button></div><div class="recommend-controls"><div class="tabs">${['all','XLSX','DOCX','PPTX'].map(f=>`<button class="pill ${homeFormat===f?'active':''}" onclick="homeFormat='${f}';render()">${f==='all'?t(11):f}</button>`).join('')}</div><select aria-label="${t(2)}" onchange="homeTask=this.value;render()"><option value="all">${t(2)}</option>${[14,15,16,17].map(i=>`<option value="${i}" ${String(homeTask)===String(i)?'selected':''}>${t(i)}</option>`).join('')}</select></div><div class="grid" id="homegrid">${rec.length?rec.map(card).join(''):`<div class="empty">${t(26)}<p>${t(27)}</p></div>`}</div></section><section class="section" id="collections"><div class="sectionhead"><div><h2>${x('collection')}</h2><p>${x('collectiondesc')}</p></div></div><div class="collections">${[...new Set(getHomeRecommendations().map(d=>d.task))].slice(0,3).map(task=>{let d=getHomeRecommendations().find(d=>d.task===task);return `<button class="collection" onclick="sceneTask=${task};go('scene')"><strong>${t(task)}</strong><small>${bi('Templates + matching visual resources','模板与配套视觉素材')}</small><span>${t(13)} →</span><div class="art">${art(d)}</div></button>`}).join('')}</div></section>${assetShelf()}${pickRow(bi('Office essentials · Excel','办公经营 · Excel'),rankResources(records.filter(d=>d.format==='XLSX'),{cap:2,limit:8}),"chooseCatalog('templates','XLSX')",bi('Budgets, invoices, payroll and everyday business.','预算、报价、薪资与日常经营。'))}${pickRow(bi('Career & documents · Word','求职人事 · Word'),rankResources(records.filter(d=>d.format==='DOCX'),{cap:3,limit:4}),"chooseCatalog('templates','DOCX')")}${pickRow(bi('Present your next idea · PowerPoint','教育与汇报 · PowerPoint'),rankResources(records.filter(d=>d.format==='PPTX'),{cap:3,limit:8}),"chooseCatalog('templates','PPTX')")}${pickRow(bi('Visual resources for your region','地区视觉素材精选'),assets,"chooseCatalog('assets')",bi('Open-source supply pilot; not a live popularity chart.','开源供给试点，非实时热度榜。'))}<section class="feature"><div class="featuretext"><div class="eyebrow">WPS OFFICE</div><h2>${x('feature')}</h2><p>${x('featuredesc')}</p><button class="primary" onclick="handoff()">${t(21)} →</button></div><img src="https://global-static.wpscdn.com/cms/official-website/v2/_nuxt/allinone_img_slides.BNaETSwm.png" alt="WPS Slides" loading="lazy" onerror="this.style.display='none'"></section><section class="benefits">${x('benefits').map((s,i)=>`<div>${icon(['edit','check','devices'][i])}<strong>${s}</strong><p>${x('benefitdesc')[i]}</p></div>`).join('')}</section></div>`};
const baseArt=art;art=function(d,pg=1){if(d.type!=='assets')return baseArt(d,pg);const src=CONFIG.artwork[d.code]?.[assetStyle];return `<div class="assetcover ${assetStyle==='black'?'outline-art':''}"><img src="${src}" alt="${esc(name(d))}" loading="lazy" width="72" height="72"></div>`};
const baseFiltered=filtered;filtered=function(){let list=baseFiltered();if(assetGroup!=='all')list=list.filter(d=>d.type==='assets'&&d.assetGroup===assetGroup);if(taskFilter)list=list.filter(d=>d.scenarios.includes(Number(taskFilter)));if(sort==='recommended')list.sort((a,b)=>recommendationScore(b)-recommendationScore(a)||a.id-b.id);return list};
listing=function(saved=false){let list=saved?records.filter(d=>saveSet.has(d.id)):filtered();let pages=Math.max(1,Math.ceil(list.length/48));browsePage=Math.max(1,Math.min(browsePage,pages));let visible=list.slice((browsePage-1)*48,browsePage*48);let counts={all:records.length,templates:records.filter(d=>d.type==='templates').length,assets:CONFIG.openmoji.length};return `<div class="wrap pagepad"><div class="bread"><button onclick="go('home')">WPS Templates</button> / ${saved?t(20):kind==='assets'?t(1):t(0)}</div><div class="browsehead"><div class="eyebrow">${saved?'YOUR LIBRARY':'EXPLORE THE LIBRARY'}</div><h1>${saved?x('saved'):taskFilter?t(taskFilter):kind==='assets'?t(1):t(0)}</h1>${saved?'':searchbox()}</div>${saved?'':`<div class="tabs">${[['all',11],['templates',0],['assets',1]].map(([k,i])=>`<button class="pill ${kind===k?'active':''}" onclick="kind='${k}';assetGroup='all';browsePage=1;render()">${t(i)} <small>${counts[k]}</small></button>`).join('')}</div><div class="filterbar"><div><select aria-label="${t(24)}" onchange="fmt=this.value;browsePage=1;render()">${['all','XLSX','DOCX','PPTX','SVG'].map(f=>`<option value="${f}" ${fmt===f?'selected':''}>${f==='all'?t(24):f}</option>`).join('')}</select><select aria-label="${t(2)}" onchange="taskFilter=this.value==='all'?null:Number(this.value);browsePage=1;render()"><option value="all">${t(2)}</option>${[14,15,16,17].map(i=>`<option value="${i}" ${taskFilter===i?'selected':''}>${t(i)}</option>`).join('')}</select><select aria-label="${t(23)}" onchange="filelang=this.value;browsePage=1;render()">${['all','English','Thai','Indonesian','Japanese','—'].map(f=>`<option value="${f}" ${filelang===f?'selected':''}>${f==='all'?x('allLanguages'):f}</option>`).join('')}</select><button class="textlink" onclick="fmt='all';filelang='all';taskFilter=null;assetGroup='all';q='';browsePage=1;render()">${t(25)}</button></div><select aria-label="Sort" onchange="sort=this.value;browsePage=1;render()">${[['recommended',bi('Regional selections','地区优先')],['name',x('name')]].map(([k,v])=>`<option value="${k}" ${sort===k?'selected':''}>${v}</option>`).join('')}</select></div>${kind==='assets'||kind==='all'?`<div class="asset-toolbar"><div class="tabs"><button class="pill ${assetGroup==='all'?'active':''}" onclick="assetGroup='all';browsePage=1;render()">${t(11)}</button>${Object.keys(groups).map(g=>`<button class="pill ${assetGroup===g?'active':''}" onclick="assetGroup='${g}';browsePage=1;render()">${assetGroupName(g)}</button>`).join('')}</div><div class="style-switch"><button class="${assetStyle==='color'?'active':''}" onclick="assetStyle='color';render()">${bi('Color','彩色')}</button><button class="${assetStyle==='black'?'active':''}" onclick="assetStyle='black';render()">${bi('Outline','线稿')}</button></div></div>`:''}`}<p class="resultcount">${list.length} ${x('count')} · ${bi('Page','页')} ${browsePage} / ${pages} · ${marketName(market)}${q?' · '+esc(q):''}</p><div class="grid">${visible.length?visible.map(card).join(''):`<div class="empty"><h2>${t(26)}</h2><p>${saved?x('emptySaved'):t(27)}</p><button class="primary" onclick="chooseCatalog('all')">${t(13)}</button></div>`}</div><div class="pagination"><button ${browsePage===1?'disabled':''} onclick="browsePage--;render();window.scrollTo(0,150)">← ${t(28)}</button>${Array.from({length:pages},(_,i)=>i+1).filter(i=>i===1||i===pages||Math.abs(i-browsePage)<=2).map(i=>`<button class="${i===browsePage?'active':''}" onclick="browsePage=${i};render();window.scrollTo(0,150)">${i}</button>`).join('')}<button ${browsePage===pages?'disabled':''} onclick="browsePage++;render();window.scrollTo(0,150)">${bi('Next','下一页')} →</button></div></div>`};
const baseDetail=detail;detail=function(){let d=records.find(d=>d.id===selected);if(d.type!=='assets')return baseDetail();let matches=rankResources(records.filter(a=>a.type==='templates'&&a.scenarios.some(s=>d.scenarios.includes(s))),{cap:2,limit:4});return `<div class="wrap"><div class="bread"><button onclick="go('browse')">${t(28)}</button> / ${assetGroupName(d.assetGroup)} / ${esc(d.en)}</div><div class="detailgrid"><div><div class="detailpreview">${art(d)}</div><div class="previewcontrols"><button onclick="assetStyle='color';render()">${bi('Color','彩色')}</button><button onclick="assetStyle='black';render()">${bi('Outline','线稿')}</button></div><p class="previewbadge">OpenMoji 15.1.0 · ${d.code} · ${esc(d.author)}</p></div><div class="detailinfo"><span class="label">${assetGroupName(d.assetGroup)}</span><h1>${esc(d.en)}</h1><p>${esc(d.tags||d.en)}</p><div class="facts"><div><small>${t(24)}</small>SVG</div><div><small>${t(23)}</small>— ${bi('No text','无文字')}</div><div><small>${x('dimensions')}</small>72 × 72 · vector</div><div><small>${x('license')}</small>CC BY-SA 4.0</div></div><a class="primary download-svg" href="${CONFIG.artwork[d.code][assetStyle]}" download="openmoji-${d.code}-${assetStyle}.svg">${bi('Download SVG','下载 SVG')} ↓</a><button class="outline" onclick="toggleSave(${d.id});render()">${saveSet.has(d.id)?'♥ '+t(20):'♡ '+t(19)}</button><div class="license" style="margin-top:20px">${bi('Designed by','作者')} ${esc(d.author)} / OpenMoji<br><a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0 ↗</a><br>${bi('Attribution and share-alike apply. Unmodified source, available offline.','使用需署名并遵守相同方式共享条件。原始素材未修改，离线可用。')}</div></div></div>${pickRow(bi('Templates to use this visual with','适合搭配使用的模板'),matches,`chooseCatalog('templates','all','${d.scenarios[0]}')`)}${pickRow(bi('More from this category','同类素材'),rankResources(records.filter(a=>a.type==='assets'&&a.id!==d.id&&a.assetGroup===d.assetGroup),{limit:12}),`chooseCatalog('assets','SVG','all','${d.assetGroup}')`)}</div>`};
const baseScene=scene;scene=function(){let templates=rankResources(records.filter(d=>d.type==='templates'&&d.scenarios.includes(sceneTask)),{cap:2,limit:8});let visuals=rankResources(records.filter(d=>d.type==='assets'&&d.scenarios.includes(sceneTask)),{cap:3,limit:12});return `<div class="wrap"><div class="bread">WPS Templates / ${t(2)} / ${marketName(market)}</div><section class="scenehero"><div><div class="eyebrow">${t(2)}</div><h1>${t(sceneTask)}</h1><p>${bi('Choose a template, then complete it with matching open-source visuals.','先选择任务模板，再搭配开源图形，完成整项工作。')}</p><button class="primary" onclick="chooseCatalog('all','all','${sceneTask}')">${t(13)} →</button></div>${art(templates[0]||records[2])}</section><div class="tabs">${[14,15,16,17].map(i=>`<button class="pill ${i===sceneTask?'active':''}" onclick="sceneTask=${i};render()">${t(i)}</button>`).join('')}</div>${pickRow('01 / '+t(0),templates,`chooseCatalog('templates','all','${sceneTask}')`)}${pickRow('02 / '+t(1),visuals,`chooseCatalog('assets','SVG','${sceneTask}')`)}</div>`};
const baseCredits=credits;credits=function(){baseCredits();$('modalbody').insertAdjacentHTML('beforeend',`<p>${CONFIG.openmoji.length} independent illustrations, each in original color and black variants. The two variants are counted as one resource. Sources embedded for offline preview and SVG download.</p><p><a href="开源素材目录.csv" download>${bi('Download source manifest','下载素材来源目录')} ↗</a> · <a href="OpenMoji-LICENSE.txt" target="_blank">OpenMoji license ↗</a></p>`)};
// Reset incompatible filters when switching top-level catalogs.
browse=function(k){chooseCatalog(k)};
taskBrowse=function(i){chooseCatalog('templates','all',i)};

;
// V4: one site header; all primary navigation belongs to Template.
let collectionPage=false;
function siteLogo(){return brand().replace('WPS Office','WPS').replace('<small>Templates</small>','<span class="brand-title">Template</span>')}
function menuLinks(){return `${[['templates',0],['assets',1]].map(([k,i])=>`<details class="site-dropdown"><summary class="site-link ${view==='browse'&&kind===k?'active':''}">${t(i)} <span>⌄</span></summary><div class="site-mega"><button class="menu-all" onclick="chooseCatalog('${k}')">${t(13)} →</button>${(k==='templates'?['XLSX','DOCX','PPTX']:Object.keys(groups)).map(v=>`<button onclick="${k==='templates'?`chooseCatalog('templates','${v}')`:`chooseCatalog('assets','SVG','all','${v}')`}">${k==='templates'?{XLSX:'Excel',DOCX:'Word',PPTX:'PowerPoint'}[v]:assetGroupName(v)}<span>→</span></button>`).join('')}</div></details>`).join('')}<button class="site-link ${view==='scene'?'active':''}" onclick="go('scene')">${t(2)}</button><button class="site-link ${view==='collections'?'active':''}" onclick="go('collections')">${t(3)}</button>`}
head=function(){document.documentElement.lang=lang;document.title=`WPS ${t(0)} — ${t(6)}`;$('header').className='template-header';$('header').innerHTML=`<button class="site-logo" onclick="go('home')" aria-label="WPS Template Home">${siteLogo()}</button><nav class="site-navigation" aria-label="${t(0)}">${menuLinks()}</nav><div class="site-actions"><button class="icon-button" onclick="globalSearch()" aria-label="${t(10)}">${icon('search')}</button><button class="icon-button saved-action ${view==='saved'?'active':''}" onclick="go('saved')" aria-label="${t(20)}">${icon('heart')}${saveSet.size?`<small>${saveSet.size}</small>`:''}</button><button class="locale-action" onclick="preferences()" aria-label="${t(31)}">${icon('globe')}<span>${locales.find(l=>l[0]===lang)[1]}<small>${marketName(market)}</small></span></button><button class="primary download-action" onclick="handoff()">${t(4)}</button><details class="mobile-site-menu"><summary aria-label="Menu">${icon('menu')}</summary><div class="mobile-menu-body">${menuLinks()}<button class="site-link" onclick="go('saved')">${icon('heart')} ${t(20)}</button><button class="site-link" onclick="preferences()">${icon('globe')} ${locales.find(l=>l[0]===lang)[1]} / ${marketName(market)}</button><button class="primary" onclick="handoff()">${t(4)}</button></div></details></div>`;footer()};
function preferences(){showModal(`<h2 class="dialogtitle" id="modal-title">${bi('Language & region','语言与地区')}</h2><p>${bi('Choose your interface language and the region used for recommendations.','分别选择界面语言与内容推荐地区。')}</p><div class="preference-panel"><label>${x('language')}<select onchange="changeLanguage(this.value);preferences()">${locales.map(([k,n])=>`<option value="${k}" ${k===lang?'selected':''}>${n}</option>`).join('')}</select></label><label>${bi('Recommendation region','内容推荐地区')}<select onchange="market=this.value;explicitMarket=true;browsePage=1;render();preferences()">${Object.keys(marketNames).map(k=>`<option value="${k}" ${k===market?'selected':''}>${marketName(k)}</option>`).join('')}</select></label></div><p class="stepnote">${bi('File language is shown on every resource. Changing the interface does not translate a file.','每项资源分别标注文件语言，切换界面不会翻译文件。')}</p><button class="primary" onclick="closeModal()">${bi('Done','完成')}</button> <button class="textlink" onclick="recommendationInfo()">${bi('About regional selections','查看地区选品依据')} →</button>`)}
languages=preferences;regions=preferences;
function globalSearch(){showModal(`<h2 class="dialogtitle" id="modal-title">${t(10)}</h2><form class="searchbox" onsubmit="event.preventDefault();q=this.querySelector('input').value;kind='all';fmt='all';filelang='all';taskFilter=null;assetGroup='all';browsePage=1;closeModal();go('browse')">${icon('search')}<input autofocus aria-label="${t(9)}" placeholder="${t(9)}" value="${esc(q)}"><button class="primary">${t(10)}</button></form><div class="popular">${Object.entries(profiles[market].weights).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([k])=>`<button onclick="closeModal();q='${k}';kind='templates';fmt='all';filelang='all';taskFilter=null;assetGroup='all';browsePage=1;go('browse')">${topicNames[k][cn()?1:0]}</button>`).join('')}</div>`)}
function collections(){let tasks=[14,15,16,17];return `<div class="wrap pagepad"><div class="bread"><button onclick="go('home')">WPS Template</button> / ${t(3)}</div><section class="browsehead"><div class="eyebrow">CURATED COLLECTIONS</div><h1>${t(3)}</h1><p>${bi('Task-focused collections that bring templates and visuals together.','围绕完整任务，把模板与配套素材组合起来。')}</p></section>${tasks.map(task=>{let items=rankResources(records.filter(d=>d.type==='templates'&&d.scenarios.includes(task)),{cap:2,limit:3});let visual=rankResources(records.filter(d=>d.type==='assets'&&d.scenarios.includes(task)),{limit:1});return pickRow(t(task),items.concat(visual),`sceneTask=${task};go('scene')`,bi('Templates and matching visual resources','任务模板与配套视觉素材'))}).join('')}</div>`}
const renderBeforeV4=render;render=function(){if(view==='collections'){head();$('main').innerHTML=collections();try{let u=new URL(location.href);u.searchParams.set('lang',lang);u.searchParams.set('market',market);u.hash='collections';history.replaceState(null,'',u)}catch(e){}}else renderBeforeV4()};
const footerBeforeV4=footer;footer=function(){footerBeforeV4();const templateLinks=`<footer class="template-footer"><div class="wrap"><div class="template-footer-top"><div>${siteLogo()}<p>${t(8)}</p></div><div><strong>${t(0)}</strong>${['XLSX','DOCX','PPTX'].map(f=>`<button onclick="chooseCatalog('templates','${f}')">${{XLSX:'Excel',DOCX:'Word',PPTX:'PowerPoint'}[f]}</button>`).join('')}</div><div><strong>${t(1)}</strong>${['office','education','arrows'].map(g=>`<button onclick="chooseCatalog('assets','SVG','all','${g}')">${assetGroupName(g)}</button>`).join('')}</div><div><strong>${t(2)}</strong>${[14,15,16,17].map(i=>`<button onclick="sceneTask=${i};go('scene')">${t(i)}</button>`).join('')}</div></div><div class="footbottom"><span>WPS Template · ${bi('Concept prototype','概念原型')}<br>${bi('Open-source illustrations by OpenMoji · CC BY-SA 4.0','开源插画来自 OpenMoji · CC BY-SA 4.0')}</span><div><button onclick="credits()">${x('sourcelink')}</button><button onclick="preferences()">${icon('globe')} ${locales.find(l=>l[0]===lang)[1]} / ${marketName(market)}</button></div></div></div></footer>`;const old=$('footer').innerHTML;const end=old.indexOf('</section>');$('footer').innerHTML=(end>=0?old.slice(0,end+10):'')+templateLinks};
// Remove duplicate region selector in homepage statistics; the header owns it.
const homeBeforeV4=home;home=function(){return homeBeforeV4().replace(/<button class="region-button" onclick="regions\(\)">[\s\S]*?<\/button>/,'')};
// The compact source drawer is closed after all navigations by the header rerender.
if(location.hash==='#collections')view='collections';

;
// V5: normalized icon family and completed resource page modules.
const iconV4=icon;icon=function(k){const paths={heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',chevron:'<path d="m6 9 6 6 6-6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>'};return paths[k]?`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[k]}</svg>`:iconV4(k)};
const cardV4=card;card=function(d){return cardV4(d).replace(/>(♥|♡)<\/button>/,`>${icon('heart')}</button>`)};
const toggleV4=toggleSave;toggleSave=function(id,b){toggleV4(id,b);if(b)b.innerHTML=icon('heart')};
function topicNavigation(){let topics=Object.entries(profiles[market].weights).sort((a,b)=>b[1]-a[1]);return `<section class="topic-nav"><div class="module-title"><strong>${bi('Browse by task','按具体任务查找')}</strong><span>${bi('Choose a task, then refine the file format and language.','先选任务，再筛选格式与文件语言。')}</span></div><div class="topic-links">${topics.map(([topic])=>{let count=records.filter(d=>d.type==='templates'&&d.topic===topic).length;return `<button onclick="openTopic('${topic}')">${topicNames[topic][cn()?1:0]} <small>${count}</small></button>`}).join('')}</div></section>`}
let topicSelection=null;
function openTopic(topic){topicSelection=topic;kind='templates';fmt='all';q='';filelang='all';assetGroup='all';taskFilter=null;browsePage=1;go('browse')}
const filterV4=filtered;filtered=function(){return filterV4().filter(d=>!topicSelection||d.topic===topicSelection)};
const chooseV4=chooseCatalog;chooseCatalog=function(...args){topicSelection=null;chooseV4(...args)};
const searchV4=globalSearch;globalSearch=function(){topicSelection=null;searchV4()};
const listingV4=listing;listing=function(saved=false){let html=listingV4(saved);html=html.replaceAll("fmt='all';filelang='all';taskFilter=null;assetGroup='all';q='';browsePage=1;render()","topicSelection=null;fmt='all';filelang='all';taskFilter=null;assetGroup='all';q='';browsePage=1;render()").replaceAll("kind='assets';assetGroup='all'","topicSelection=null;kind='assets';assetGroup='all'");if(saved){return html.replace('</h1>',`</h1><p>${bi('Keep templates and visuals together. Your saved resources stay in this browser.','把模板与素材保存在一起，收藏会保留在当前浏览器。')}</p>`)}if(kind!=='assets'){const marker='<div class="tabs">';html=html.replace(marker,`${topicNavigation()}${marker}`)}if(topicSelection){html=html.replace('<div class="filterbar">',`<div class="selected-topic"><span>${topicNames[topicSelection][cn()?1:0]}</span><button onclick="topicSelection=null;browsePage=1;render()" aria-label="${t(25)}">${icon('close')}</button></div><div class="filterbar">`)}return html};
const detailV4=detail;detail=function(){let d=records.find(d=>d.id===selected);let html=detailV4();if(d.type==='templates'){const guide=`<section class="resource-guide"><div><div class="eyebrow">${bi('ABOUT THIS TEMPLATE','模板说明')}</div><h2>${esc(name(d))}</h2><p>${bi('A structured starting point for','用于下列任务的结构化起点：')} ${topicNames[d.topic]?.[cn()?1:0]||t(d.task)}.</p><dl><div><dt>${bi('Best for','适用场景')}</dt><dd>${d.scenarios.map(i=>t(i)).join(' / ')}</dd></div><div><dt>${bi('File format','文件格式')}</dt><dd>${d.format}</dd></div><div><dt>${bi('File language','文件语言')}</dt><dd>${d.filelang}</dd></div><div><dt>${bi('Preview license','封面许可')}</dt><dd>CC0</dd></div></dl></div><div><h3>${bi('Make it yours','开始使用')}</h3><ol><li>${bi('Check the format, language and preview before choosing.','先核对格式、文件语言与预览内容。')}</li><li>${bi('Replace sample text and values with your own information.','使用时替换示例文字与数值，并检查结果。')}</li><li>${bi('Open in WPS to edit and save when an editable file is connected.','接入可编辑文件后，可在 WPS 中编辑并保存。')}</li></ol><div class="license">${bi('This resource currently contains an original concept cover. Editable Office files, formula validation and compatibility verification have not been connected.','当前资源为原创概念封面，尚未接入可编辑 Office 文件、公式校验和兼容性验证。')}</div></div></section>`;html=html.replace('<section class="scene-step">',guide+'<section class="scene-step">')}else{html=html.replace('<div class="detailgrid">',`<div class="detailgrid">`);const idx=html.indexOf('<section class="section dense-section">');const guide=`<section class="resource-guide asset-guide"><div><h2>${bi('Use this visual in your work','将素材用于你的作品')}</h2><p>${bi('Download the original SVG, then insert it into a document or presentation that supports SVG.','下载原始 SVG，再插入支持该格式的文件或演示文稿。')}</p></div><div><h3>${bi('Attribution','署名参考')}</h3><div class="attribution-text">${esc(d.en)} — ${esc(d.author)} / OpenMoji, CC BY-SA 4.0.</div><p>${bi('If you modify the artwork, indicate changes and follow the share-alike license.','如修改图形，应注明修改，并遵守相同方式共享许可。')}</p></div></section>`;if(idx>=0)html=html.slice(0,idx)+guide+html.slice(idx)}return html};
const sceneV4=scene;scene=function(){return sceneV4().replace('<div class="tabs">',`<section class="workflow-strip">${[[icon('search'),bi('Find a starting point','选择任务模板')],[icon('grid'),bi('Add matching visuals','搭配视觉素材')],[icon('edit'),bi('Personalize your work','编辑自己的内容')]].map(([ico,label],i)=>`<div><span>${ico}</span><strong>0${i+1}</strong><p>${label}</p></div>`).join('')}</section><div class="tabs">`)};
const homeV4=home;home=function(){const faq=`<section class="faq"><h2>${x('faqt')}</h2>${x('faq').map((title,i)=>`<details><summary>${title}</summary><p>${x('answers')[i]}</p></details>`).join('')}</section>`;let html=homeV4();let pos=html.lastIndexOf('</div>');return html.slice(0,pos)+faq+html.slice(pos)};
const headV4=head;head=function(){headV4();$('header').innerHTML=$('header').innerHTML.replace(/ <span>⌄<\/span>/g,icon('chevron'));};
render();

;
// V6: template detail follows the supplied preview/gallery + information layout.
let previewById={};
function previewDescription(d,n){const steps=cn()?['封面与任务介绍','内容结构与关键要点','示例内容与使用说明']:['Cover and task overview','Structure and key points','Sample content and usage'];return `${steps[n-1]} · ${name(d)}`}
function templateFrame(d,n){return `<div class="template-slide">${art(d,n)}</div>`}
function setTemplatePage(n){page=n;previewById[selected]=n;render()}
const detailV5=detail;
detail=function(){let d=records.find(d=>d.id===selected);if(d.type!=='templates')return detailV5();const n=previewById[d.id]||1;page=n;const formatInfo={PPTX:{letter:'P',color:'orange',title:bi('Presentation template','简报模板'),ratio:'16:9',application:'Microsoft PowerPoint'},XLSX:{letter:'S',color:'green',title:bi('Spreadsheet template','表格模板'),ratio:bi('Worksheet preview','工作表预览'),application:'Microsoft Excel'},DOCX:{letter:'W',color:'',title:bi('Document template','文档模板'),ratio:bi('Portrait preview','纵向预览'),application:'Microsoft Word'}}[d.format];const matches=rankResources(records.filter(a=>a.type==='assets'&&a.scenarios.some(s=>d.scenarios.includes(s))),{cap:2,limit:8});const similar=rankResources(records.filter(a=>a.type==='templates'&&a.id!==d.id&&(a.topic===d.topic||a.format===d.format)),{cap:2,limit:4});return `<div class="wrap template-detail-page"><nav class="template-breadcrumb" aria-label="Breadcrumb"><button onclick="go('home')">${bi('Home','首页')}</button><span>›</span><button onclick="chooseCatalog('templates')">${t(0)}</button><span>›</span><strong>${esc(name(d))}</strong></nav><section class="template-product"><div class="template-gallery"><div class="template-main-preview">${templateFrame(d,n)}<div class="template-caption"><span>${esc(previewDescription(d,n))}</span><strong>${n}<i>/3</i></strong></div></div><div class="template-thumbnails" aria-label="${bi('Preview pages','预览页面')}"><button class="gallery-arrow" onclick="setTemplatePage(Math.max(1,${n}-1))" ${n===1?'disabled':''} aria-label="Previous">‹</button>${[1,2,3].map(i=>`<button class="template-thumb ${i===n?'selected':''}" onclick="setTemplatePage(${i})" aria-label="${bi('Preview page','预览页')} ${i}" aria-pressed="${i===n}">${templateFrame(d,i)}<span>${i}</span></button>`).join('')}<button class="gallery-arrow" onclick="setTemplatePage(Math.min(3,${n}+1))" ${n===3?'disabled':''} aria-label="Next">›</button></div></div><div class="template-product-info"><div class="template-type"><span class="appicon ${formatInfo.color}">${formatInfo.letter}</span>${formatInfo.title}</div><h1>${esc(name(d))}</h1><div class="template-summary"><p>${bi('Format','格式')}：<strong>${d.format}</strong> <span>|</span> ${bi('3 concept previews','3 页概念预览')} <span>|</span> ${bi('Style: Professional','风格：专业')}</p><p>${bi('Category','类别')}：${topicNames[d.topic]?.[cn()?1:0]||t(d.task)}</p></div><div class="application-chips"><span>WPS Office</span><span>${formatInfo.application}</span><span>${d.filelang}</span></div><div class="template-price">${bi('Free preview','免费预览')}<small>CC0</small></div><div class="template-product-actions"><button class="primary" onclick="templateDownloadInfo(${d.id})">${icon('download')} ${bi('Download','下载')}</button><button class="primary" onclick="handoff(${d.id})">${bi('Open in WPS Office','在 WPS Office 中开启')}</button></div><p class="template-availability">${bi('Concept preview only. Editable Office files are not connected yet.','当前为概念预览，尚未接入可编辑 Office 文件。')}</p><dl class="template-attributes"><div><dt>${bi('File language','文件语言')}</dt><dd>${d.filelang}</dd></div><div><dt>${bi('File size','文件大小')}</dt><dd>${bi('Not supplied','尚未提供')}</dd></div><div><dt>${bi('Layout','页面比例')}</dt><dd>${formatInfo.ratio}</dd></div><div><dt>${bi('Preview license','预览授权')}</dt><dd>CC0</dd></div><div><dt>${bi('Editable file license','可编辑文件授权')}</dt><dd>${bi('Not supplied','尚未提供')}</dd></div></dl><button class="template-save" onclick="toggleSave(${d.id});render()">${icon('heart')} ${saveSet.has(d.id)?t(20):t(19)}</button></div></section><section class="resource-guide template-details-below"><div><div class="eyebrow">${bi('ABOUT THIS TEMPLATE','模板说明')}</div><h2>${topicNames[d.topic]?.[cn()?1:0]||t(d.task)}</h2><p>${bi('A structured starting point for your next task. Review the format, file language and preview before choosing.','为你的下一项任务提供结构起点。选用前请确认格式、文件语言与预览内容。')}</p><div class="topic-links">${d.scenarios.map(i=>`<button onclick="chooseCatalog('templates','all',${i})">${t(i)} →</button>`).join('')}</div></div><div><h3>${bi('How to use','使用方式')}</h3><ol><li>${bi('Browse the preview pages and check resource details.','浏览预览页面并核对资源信息。')}</li><li>${bi('When a file is available, replace the example text and values.','接入文件后，替换示例文字和数值。')}</li><li>${bi('Check your content before editing and saving in WPS.','检查内容后，在 WPS 中编辑和保存。')}</li></ol></div></section>${pickRow(t(22),similar,`chooseCatalog('templates','${d.format}')`)}${pickRow(bi('Complete your template with matching visuals','为模板搭配合适的视觉素材'),matches,`chooseCatalog('assets','SVG','${d.scenarios[0]}')`)}</div>`};
function templateDownloadInfo(id){const d=records.find(d=>d.id===id);showModal(`<h2 class="dialogtitle" id="modal-title">${esc(name(d))}</h2><p>${bi('This resource currently includes concept previews, not an editable Office file.','当前资源包含概念预览，尚未提供可编辑的 Office 文件。')}</p><div class="stepnote">${bi('The download area demonstrates the intended product layout. File size, compatibility, page count and license must be filled from the actual file before publishing.','下载区域用于展示产品布局。正式发布前，需要根据实际文件补齐文件大小、兼容性、页数与授权信息。')}</div><p><button class="primary" onclick="closeModal()">${bi('Back to preview','返回预览')}</button></p>`)}
