['en-US','en','US','United States','English','Americas'],['en-PH','en','PH','Philippines','English','Asia Pacific'],['fil-PH','fil','PH','Pilipinas','Filipino','Asia Pacific'],['th-TH','th','TH','ประเทศไทย','ไทย','Asia Pacific'],['en-MY','en','MY','Malaysia','English','Asia Pacific'],['ms-MY','ms','MY','Malaysia','Melayu','Asia Pacific'],['id-ID','id','ID','Indonesia','Bahasa Indonesia','Asia Pacific'],['en-ID','en','ID','Indonesia','English','Asia Pacific'],['en-PK','en','PK','Pakistan','English','Asia Pacific'],['en-IN','en','IN','India','English','Asia Pacific'],['hi-IN','hi','IN','भारत','हिंदी','Asia Pacific'],['en-SG','en','GLOBAL','Singapore','English','Asia Pacific'],['en-GB','en','GLOBAL','United Kingdom','English','Europe'],['en-AU','en','GLOBAL','Australia','English','Asia Pacific'],['de-DE','de','GLOBAL','Deutschland','Deutsch','Europe'],['es-ES','es','GLOBAL','España','Español','Europe'],['es-MX','es','GLOBAL','México','Español','Americas'],['fr-FR','fr','GLOBAL','France','Français','Europe'],['pl-PL','pl','GLOBAL','Polska','Polski','Europe'],['pt-BR','pt-BR','GLOBAL','Brasil','Português','Americas'],['ru-RU','ru','GLOBAL','Россия','Русский','Europe'],['it-IT','it','GLOBAL','Italia','Italiano','Europe'],['ja-JP','ja','GLOBAL','日本','日本語','Asia Pacific'],['vi-VN','vi','GLOBAL','Việt Nam','Tiếng Việt','Asia Pacific'],['zh-Hant-TW','zh-Hant','GLOBAL','台灣','繁體中文','Asia Pacific'],['zh-Hant-HK','zh-Hant','GLOBAL','香港特別行政區','繁體中文','Asia Pacific'],['tr-TR','tr','GLOBAL','Türkiye','Türkçe','Europe'],['en-001','en','GLOBAL','Global','English','Global']
