let currentLocale=null,localeReturnView=view==='locale'?'home':view,localeSearch='',localeArea='all';
function resolveLocale(){let direct=siteLocales.find(l=>l.id.toLowerCase()===(params.get('locale')||'').toLowerCase());if(direct)return direct;let oldLanguage=params.get('lang'),oldMarket=params.get('market');if(oldLanguage||oldMarket){return siteLocales.find(l=>l.language===oldLanguage&&l.profile===oldMarket)||siteLocales.find(l=>l.language===oldLanguage)||siteLocales.find(l=>l.profile===oldMarket)||siteLocales[0]}try{let saved=localStorage.getItem('wps-template-locale-v1');let entry=siteLocales.find(l=>l.id===saved);if(entry)return entry}catch(e){}return siteLocales[0]}
