changeLanguage=function(language){const entry=siteLocales.find(l=>l.language===language&&l.country===currentLocale.country)||siteLocales.find(l=>l.language===language);if(entry)selectLocale(entry.id)};
setMarket=function(profile){const entry=siteLocales.find(l=>l.profile===profile&&l.language===lang)||siteLocales.find(l=>l.profile===profile);if(entry)selectLocale(entry.id)};
function localePage(){return `<div class="wrap locale-page"><nav class="template-breadcrumb"><button onclick="view=localeReturnView;render()">${t(28)}</button><span>›</span><strong>${bi('Country / region & language','地区与语言')}</strong></nav><div class="locale-intro"><div class="eyebrow">WPS TEMPLATE · WORLDWIDE</div><h1>${bi('Choose your country or region','选择你的地区与语言')}</h1><p>${bi('Select a country or region and language to explore templates and visuals for your work.','选择地区与语言版本，浏览适合工作与学习的模板和素材。')}</p><div class="current-locale">${icon('globe')}<span>${bi('Current selection','当前版本')}：<strong>${esc(localeLabel())}</strong></span></div></div><div class="locale-search"><label>${icon('search')}<input aria-label="${bi('Find a country or language','查找地区或语言')}" placeholder="${bi('Find a country, region or language','搜索地区或语言')}" value="${esc(localeSearch)}" oninput="localeSearch=this.value;updateLocaleResults()"></label><select aria-label="${bi('Region group','地区分组')}" onchange="localeArea=this.value;updateLocaleResults()"><option value="all">${bi('All regions','全部地区')}</option>${['Asia Pacific','Europe','Americas','Global'].map(a=>`<option ${localeArea===a?'selected':''}>${a}</option>`).join('')}</select></div><div id="locale-results">${localeResults()}</div><div class="locale-bottom-note">${bi('Your selection sets the interface language and regional recommendations together. File language remains shown separately on every resource.','地区与语言作为一个版本切换，界面与推荐同步更新；资源的文件语言仍分别标注。')}</div></div>`}
function localeResults(){let query=localeSearch.trim().toLocaleLowerCase();let list=siteLocales.filter(l=>(localeArea==='all'||l.area===localeArea)&&(!query||`${l.id} ${l.country} ${l.languageName} ${l.area}`.toLocaleLowerCase().includes(query)));if(!list.length)return `<div class="empty"><h2>${t(26)}</h2><p>${bi('Try a country name, language or locale code.','可搜索地区名、语言名或 locale 代码。')}</p></div>`;return `<div class="locale-count">${list.length} ${bi('available versions','个可选版本')}</div><div class="locale-grid">${list.slice().sort((a,b)=>a.country.localeCompare(b.country,'en')).map(l=>`<a lang="${l.language}" href="?locale=${encodeURIComponent(l.id)}#${localeReturnView==='detail'?'resource-'+selected:localeReturnView}" class="locale-option ${l.id===currentLocale.id?'selected':''}" ${l.id===currentLocale.id?'aria-current="true"':''} onclick="event.preventDefault();selectLocale('${l.id}')"><span>${esc(l.country)} <i>—</i> ${esc(l.languageName)}</span>${l.id===currentLocale.id?icon('check'):'<span class="locale-option-arrow">→</span>'}</a>`).join('')}</div>`}
function updateLocaleResults(){$('locale-results').innerHTML=localeResults()}
const headV6=head;head=function(){headV6();$('header').innerHTML=$('header').innerHTML.replace(/<button class="locale-action"[\s\S]*?<\/button>/,`<button class="locale-action bound-locale" onclick="openLocale()" aria-label="${bi('Change country and language','切换地区与语言')}">${icon('globe')}<span>${esc(currentLocale.languageName)}<small>${esc(currentLocale.country)}</small></span></button>`);};
const footerV6=footer;footer=function(){footerV6();$('footer').innerHTML=$('footer').innerHTML.replace(/<button onclick="preferences\(\)">[\s\S]*?<\/button>/g,`<button onclick="openLocale()">${icon('globe')} ${esc(localeLabel())}</button>`)};
const renderV6=render;render=function(){if(view==='locale'){head();$('main').innerHTML=localePage()}else renderV6();try{let u=new URL(location.href);u.searchParams.delete('lang');u.searchParams.delete('market');u.searchParams.set('locale',currentLocale.id);u.hash=view==='detail'?`resource-${selected}`:view;history.replaceState(null,'',u)}catch(e){}};
const recommendationV6=recommendationInfo;recommendationInfo=function(){recommendationV6();if(currentLocale.profile==='GLOBAL'&&currentLocale.id!=='en-001')$('modalbody').insertAdjacentHTML('beforeend',`<p class="stepnote">${bi('This locale currently uses global office selections. A dedicated regional popularity model has not been validated.','当前地区暂时采用全球办公精选，尚未验证独立的地区热门模型。')}</p>`)};
