// V9: one visual category entry point, no duplicated category wall.
function visualCategoryRail(){const cats=orderedCategories();return `<section class="visual-category-section" aria-label="${bi('Template categories','模板分类')}"><div class="visual-category-heading"><span>${bi('Start with your task','选择你要完成的任务')}</span><div><button class="rail-arrow" onclick="slideCategoryRail(-1)" aria-label="${bi('Previous categories','上一组分类')}">‹</button><button class="rail-arrow" onclick="slideCategoryRail(1)" aria-label="${bi('Next categories','下一组分类')}">›</button><button class="rail-all" onclick="chooseCatalog('templates')">${t(13)} →</button></div></div><div class="visual-category-rail" id="category-rail">${cats.map(c=>{let d=rankResources(categoryResources(c.id),{limit:1})[0]||categoryResources(c.id)[0];return `<button class="visual-category-card" onclick="openCategory('${c.id}')"><div class="visual-category-art">${art(d)}</div><div class="visual-category-copy"><strong>${taxLabel(c)}</strong><span>${c.leaves.slice(0,3).map(leafLabel).join(' · ')}</span><small>${categoryResources(c.id).length} ${bi('concept previews','项概念预览')} <i>→</i></small></div></button>`}).join('')}</div></section>`}
function slideCategoryRail(direction){const rail=$('category-rail');rail.scrollBy({left:direction*Math.max(260,rail.clientWidth*.8),behavior:'smooth'})}
function completeSceneCollections(){const tasks=[14,15,16,17];const titles={14:bi('Run your business','经营你的企业'),15:bi('Take your next career step','迎接下一个职涯机会'),16:bi('Prepare a better lesson','准备一堂好课'),17:bi('Keep your project moving','推动项目进展')};return `<section class="section task-bundles" id="collections"><div class="sectionhead"><div><h2>${bi('One task. Everything you need.','一项任务，配齐所需资源')}</h2><p>${bi('Start with a template. Add the visuals that fit.','从模板开始，搭配合适的视觉素材。')}</p></div><button class="textlink" onclick="go('collections')">${t(13)} →</button></div><div class="task-bundle-grid">${tasks.map(task=>{const d=rankResources(records.filter(d=>d.type==='templates'&&d.scenarios.includes(task)),{limit:1})[0]||records.find(d=>d.type==='templates'&&d.scenarios.includes(task));const visual=rankResources(records.filter(a=>a.type==='assets'&&a.scenarios.includes(task)),{limit:1})[0];return `<button class="task-bundle" onclick="sceneTask=${task};go('scene')"><div class="task-bundle-copy"><small>${t(task)}</small><h3>${titles[task]}</h3><span>${bi('Templates + matching visuals','模板＋配套素材')} →</span></div><div class="task-bundle-art">${art(d)}${visual?`<div class="bundle-visual">${art(visual)}</div>`:''}</div></button>`}).join('')}</div></section>`}
const homeV8=home;home=function(){let html=homeV8();html=html.replace(/<div class="showcase"[\s\S]*?<\/div><\/section>/,visualCategoryRail()+'</section>');const start=html.indexOf('<section class="category-overview"');if(start>=0){const end=html.indexOf('</section>',start)+10;html=html.slice(0,start)+html.slice(end)}html=html.replace(/<div class="catalog-bar">[\s\S]*?<\/div><div class="formats">/,'<div class="formats">');const collectionsStart=html.indexOf('<section class="section" id="collections">');if(collectionsStart>=0){const end=html.indexOf('</section>',collectionsStart)+10;html=html.slice(0,collectionsStart)+completeSceneCollections()+html.slice(end)}
// Main page: search/category rail -> format shortcuts -> recommendations -> complete task sets -> asset categories.
// Format-specific long lists remain in the catalog instead of repeating the same resources on the homepage.
const titles=[bi('Office essentials · Excel','办公经营 · Excel'),bi('Career & documents · Word','求职人事 · Word'),bi('Present your next idea · PowerPoint','教育与汇报 · PowerPoint')];for(const title of titles){const marker='<section class="section dense-section"><div class="sectionhead"><div><h2>'+title+'</h2>';const at=html.indexOf(marker);if(at>=0){const end=html.indexOf('</section>',at)+10;html=html.slice(0,at)+html.slice(end)}}return html};
render();

