const ui11=i=>I18N11.rows[lang][i];
const groupKeys11=['office','finance','education','arrows','charts','nature','travel','activities'];
const fileLanguageKeys11={en:'English','de':'German',es:'Spanish',fr:'French',id:'Indonesian',pl:'Polish','pt-BR':'Portuguese',ru:'Russian',hi:'Hindi',fil:'Filipino',ms:'Malay',it:'Italian',ja:'Japanese',th:'Thai',vi:'Vietnamese','zh-Hant':'Chinese',tr:'Turkish'};
const countrySecondLanguage11=new Set(['PH','MY','IN','HK','SG','PK']);
function localeCountry11(l=currentLocale){return l.id==='en-001'?'001':l.id.split('-').at(-1)}
function languagePolicy11(l=currentLocale){const primary=fileLanguageKeys11[l.language];const country=localeCountry11(l);return {primary,secondary:primary!=='English'&&countrySecondLanguage11.has(country)?['English']:[],allow:[primary,...(primary!=='English'&&countrySecondLanguage11.has(country)?['English']:[])]}}
