head=function(){document.documentElement.lang=lang;document.title=`WPS Template · ${t(0)}`;$('header').className='template-header';$('header').innerHTML=`<button class="site-logo" onclick="go('home')">${siteLogo()}</button><nav class="site-navigation">${menu11()}</nav><div class="site-actions"><button class="icon-button" onclick="globalSearch()" aria-label="${t(10)}">${icon('search')}</button><button class="icon-button" onclick="go('saved')" aria-label="${t(20)}">${icon('heart')}</button><button class="locale-action" onclick="openLocale()" aria-label="${ui11(15)}">${icon('globe')}<span>${esc(nativeLocaleLabel11())}</span></button><button class="primary download-action" onclick="handoff()">${t(4)}</button><details class="mobile-site-menu"><summary aria-label="${t(11)}">${icon('menu')}</summary><div class="mobile-menu-body">${menu11()}<button class="site-link" onclick="openLocale()">${ui11(15)}</button></div></details></div>`;footer()};
