home=function(){let rec=rankResources(records.filter(d=>d.type==='templates'),{cap:2,limit:12});return `<section class="hero"><h1>${t(6)}<br><span>${t(7)}</span></h1><p>${t(8)}</p>${searchbox()}${rail11()}</section><div class="wrap">${rec.length?row11(ui11(3),rec,"chooseCatalog('templates')"):`<section class="section native-supply-note"><p>${ui11(4)}</p><button class="textlink" onclick="chooseCatalog('assets')">${ui11(5)} →</button></section>`}${assetGroups11()}${row11(ui11(28),rankResources(records.filter(d=>d.type==='assets'),{cap:2,limit:12}),"chooseCatalog('assets')")}</div>`};
