scene=function(){let list=rankResources(records.filter(d=>d.type==='templates'&&d.scenarios.includes(sceneTask)),{cap:2,limit:8});let visual=rankResources(records.filter(d=>d.type==='assets'&&d.scenarios.includes(sceneTask)),{cap:2,limit:12});return `<div class="wrap"><section class="browsehead"><h1>${t(sceneTask)}</h1><div class="tabs">${[14,15,16,17].map(i=>`<button class="pill ${i===sceneTask?'active':''}" onclick="sceneTask=${i};render()">${t(i)}</button>`).join('')}</div></section>${list.length?row11(t(0),list,`chooseCatalog('templates','all',${sceneTask})`):`<p class="native-supply-note">${ui11(4)}</p>`}${row11(t(1),visual,`chooseCatalog('assets','SVG',${sceneTask})`)}</div>`};
