footer=function(){const f=footerCopy13[lang];$('footer').innerHTML=`<footer class="reference-footer" aria-label="${f[0]} / ${f[1]} / ${f[2]}"><div class="wrap"><div class="reference-footer-grid"><section class="footer-company-address"><button class="footer-brand" onclick="go('home')" aria-label="WPS Template">${siteLogo()}</button><address>WPS SOFTWARE PTE. LTD.<br>6 RAFFLES QUAY #14-06<br>SINGAPORE (048580)</address><button class="footer-source" onclick="credits()">${f[14]} ↗</button><span class="footer-open-source">OpenMoji · CC BY-SA 4.0</span></section><nav class="footer-nav-column" aria-label="${f[0]}"><h2>${f[0]}</h2>${footerProducts13.map(([label,url])=>footerExternal13(typeof label==='number'?f[label]:label,url)).join('')}</nav><nav class="footer-nav-column" aria-label="${f[1]}"><h2>${f[1]}</h2>${footerExternal13(f[3],'https://www.wps.com/about-us/')}${footerExternal13(f[4],'https://www.wps.com/strategic-partner/')}${footerExternal13(f[5],'https://www.wps.com/partners-oem/')}<a href="?locale=${currentLocale.id}#browse" onclick="event.preventDefault();chooseCatalog('templates')">${t(0)}</a>${footerExternal13(f[6],'https://www.wps.com/privacy-policy/')}</nav><nav class="footer-nav-column" aria-label="${f[2]}"><h2>${f[2]}</h2>${footerExternal13(f[7],'https://www.wps.com/support/')}${footerExternal13(f[8],'https://help.wps.com/')}${footerExternal13(f[9],'https://www.wps.com/academy/')}${footerExternal13(f[10],'https://www.wps.com/whatsnew/pc/')}</nav></div><div class="reference-footer-bottom"><button class="footer-locale" onclick="openLocale()">${icon('globe')}<span>${esc(nativeLocaleLabel11())}</span>${icon('chevron')}</button><button class="footer-all-locales" onclick="openLocale()">${f[12]} →</button><p>Copyright © Kingsoft Office Software. ${f[13]}.</p></div></div></footer>`};
// Footer translations are complete per locale; do not strip them with legacy text fallback logic.
const renderBefore13=render;render=function(){renderBefore13();footer()};
