function quickLocaleLink14(id){const entry=siteLocales.find(l=>l.id===id);if(!entry)return '';let returnHash=view==='detail'?'resource-'+selected:view;return `<a lang="${entry.language}" href="?locale=${entry.id}#${returnHash}" role="menuitemradio" aria-checked="${currentLocale.id===entry.id}" class="quick-locale-item ${currentLocale.id===entry.id?'selected':''}" onclick="event.preventDefault();applyQuickLocale14('${id}')">${quickLocaleLabels14[id]}</a>`}
function quickLocalePanel14(){let currentVisible=quickLocaleIds14.includes(currentLocale.id);return `<div class="quick-locale-panel" role="menu" aria-label="${footerCopy13[lang][12]}">${!currentVisible?`<div class="quick-locale-current">${icon('check')} ${esc(nativeLocaleLabel11())}</div>`:''}<div class="quick-locale-columns"><div>${quickLocaleIds14.slice(0,9).map(quickLocaleLink14).join('')}</div><div>${quickLocaleIds14.slice(9).map(quickLocaleLink14).join('')}<a class="quick-locale-all" href="?locale=${currentLocale.id}#locale" role="menuitem" onclick="event.preventDefault();closeQuickLocale14();openLocale()">${footerCopy13[lang][12]} <span aria-hidden="true">↗</span></a></div></div></div>`}
function closeQuickLocale14(){const menu=document.getElementById('header-locale-picker');if(menu){menu.open=false;menu.querySelector?.('summary')?.setAttribute('aria-expanded','false')}}
function applyQuickLocale14(id){localeReturnView=view==='locale'?localeReturnView:view;closeQuickLocale14();selectLocale(id)}
const headBefore14=head;head=function(){headBefore14();const button=`<details class="header-locale-picker" id="header-locale-picker"><summary class="header-globe-trigger" aria-label="${footerCopy13[lang][12]}" aria-haspopup="menu" aria-expanded="false" onclick="closeOtherHeaderMenus14(event)">${icon('globe')}</summary>${quickLocalePanel14()}</details>`;$('header').innerHTML=$('header').innerHTML.replace(/<button class="locale-action[^\"]*"[\s\S]*?<\/button>/,button)};
function closeOtherHeaderMenus14(event){const trigger=event.currentTarget;const picker=trigger.parentElement;document.querySelectorAll('.template-header details[open]').forEach(d=>{if(d!==picker&&!d.contains(picker))d.open=false});trigger.setAttribute('aria-expanded',picker.open?'false':'true')}
// Pointer dismissal does not interfere with native details keyboard activation.
if(document.addEventListener){document.addEventListener('pointerdown',e=>{const picker=document.getElementById('header-locale-picker');if(picker?.open&&!picker.contains(e.target))closeQuickLocale14()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const picker=document.getElementById('header-locale-picker');if(picker?.open){const trigger=picker.querySelector('summary');closeQuickLocale14();trigger?.focus()}}});}
const localizeBefore14=localizeInterface12;localizeInterface12=function(html){const protectedPanels=[];let masked=html.replace(/<div class="quick-locale-panel"[\s\S]*?<\/div><\/div><\/div>/g,m=>{protectedPanels.push(m);return `<!--QUICK_LOCALE_${protectedPanels.length-1}-->`});masked=localizeBefore14(masked);return masked.replace(/<!--QUICK_LOCALE_(\d+)-->/g,(_,i)=>protectedPanels[Number(i)])};
