function categoryTile16(category,leaf=null){const pool=categoryResources(category.id).filter(d=>!leaf||d.taxLeaf===leaf[0]);const d=rankResources(pool,{limit:1})[0]||pool[0];if(!d)return '';let title=leaf?(leafLabel(leaf)||name(d)):taxLabel(category);if(!title)return '';const action=leaf?`openCategory('${category.id}','${leaf[0]}')`:`openCategory('${category.id}')`;return `<button class="category-tile16 cat-${category.id}" onclick="${action}" aria-label="${esc(title)}"><span class="category-tile-copy16"><strong>${esc(title)}</strong><small>${leaf?taxLabel(category):`${pool.length} · ${d.format}`}</small></span><span class="category-tile-art16" aria-hidden="true"><span class="tile-paper-back16"></span><span class="tile-paper-front16">${art(d)}</span></span></button>`}
